// The run, in the shape workflow 03 reads. Postings in their original order, with the reason for every decision.
const run = $('Run in').first().json;
const rows = $('Judge (rules = keywords.json v0.5.2)').all().map(i => i.json);
const FIELDS = ['source', 'company', 'source_id', 'title', 'text', 'url', 'location_text', 'department', 'date_posted', 'job_ref', 'kept', 'matched', 'reject_reason'];
const records = rows.map(r => { const o = {}; for (const f of FIELDS) o[f] = r[f] === undefined ? null : r[f]; return o; });
const rejected = {};
if (run.views.length > rows.length) rejected.duplicate = run.views.length - rows.length;
for (const r of records) if (r.reject_reason) rejected[r.reject_reason] = (rejected[r.reject_reason] || 0) + 1;
return [{json: {date: run.date, keywords_version: '0.5.2', sources: run.sources, watched: run.watched || [...new Set(run.sources.map(s => s.company))],
  counts: {postings_fetched: run.views.length, postings_unique: records.length, kept: records.filter(r => r.kept).length, rejected}, records}}];
